mapper.select:
SELECT b.* FROM blog_post b

    LEFT JOIN document_content draft
        ON draft.document_id = b.document_id AND draft.stage = #{draftStage} AND #{manage}
    LEFT JOIN document_content published
        ON published.document_id = b.document_id AND published.stage = #{publishedStage}



        b.status = #{status}


        AND (
            strpos(LOWER(CASE WHEN draft.id IS NOT NULL THEN draft.title ELSE published.title END),
                    LOWER(#{keyword})) > 0
            OR strpos(LOWER(b.slug), LOWER(#{keyword})) > 0
        )


ORDER BY b.published_at DESC, b.id DESC

SELECT EXISTS (
    SELECT 1 FROM blog_post
    WHERE LOWER(slug) = LOWER(#{slug})

        AND id != #{id}

)
